import './style.css';

document.querySelector('#app').innerHTML=`<div class="grain"></div><header><div class="brand"><span class="bolt">W</span><div><b>WRESTLING</b><strong>LEGENDS</strong></div></div><button id="sound" class="icon-btn">♪</button></header><main><section class="arena"><div class="crowd"></div><div class="spotlight left"></div><div class="spotlight right"></div><div class="stage-title">ROUND 1 <i></i> LEGEND'S ARENA</div><canvas id="game" width="960" height="540"></canvas><div class="hud"><div class="fighter-card"><div class="portrait p1"><span>R</span></div><div class="fighter-info"><div class="name-row"><b>ROCKY REX</b><em id="pState">READY</em></div><div class="bar"><div id="pHealth"></div></div><div class="bar stamina"><div id="pStamina"></div></div></div></div><div class="timer"><small>ROUND</small><b id="timer">01:30</b></div><div class="fighter-card cpu"><div class="fighter-info"><div class="name-row"><em id="eState">READY</em><b>THE VIPER</b></div><div class="bar"><div id="eHealth"></div></div><div class="bar stamina"><div id="eStamina"></div></div></div><div class="portrait p2"><span>V</span></div></div></div></section><aside><div class="card match"><span>MATCH 01</span><div class="vs"><b>RR</b><i>VS</i><b>TV</b></div><small>SINGLE MATCH</small></div><div class="card controls"><h3>CONTROLS</h3><div><kbd>A</kbd><kbd>D</kbd><span>MOVE</span></div><div><kbd>W</kbd><span>JUMP</span></div><div><kbd>J</kbd><span>PUNCH</span></div><div><kbd>K</kbd><span>KICK</span></div><div><kbd>L</kbd><span>GRAPPLE</span></div></div></aside></main><div id="overlay" class="overlay"><div class="poster"><small>LEGEND'S ARENA</small><h1>WRESTLING<br><span>LEGENDS</span></h1><p id="overlaySub">ONE RING. ONE CHAMPION.</p><button id="start">ENTER THE RING <b>→</b></button></div></div><div id="toast"></div>`;

const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const keys={},p={x:260,y:410,vx:0,vy:0,h:100,s:100,facing:1,attack:0,hit:0,grapple:0},e={x:690,y:410,vx:0,vy:0,h:100,s:100,facing:-1,attack:0,hit:0,grapple:0};
let active=false,ended=false,time=90,last=performance.now(),aiTimer=0;
const $=id=>document.querySelector(id);
addEventListener('keydown',x=>{keys[x.key.toLowerCase()]=true;if(['a','d','w','j','k','l','arrowleft','arrowright','arrowup',' '].includes(x.key.toLower())x.preventDefault()});
addEventListener('keyup',x=>keys[x.key.toLowerCase()]=false);
function toast(t){const q=$('toast');q.textContent=t;q.classList.remove('show');void q.offsetWidth;q.classList.add('show')}
function attack(a,b,type){if(a.attack||a.hit||a.s<12)return;a.attack=22;a.s-=12;const dist=Math.abs(a.x-b.x);if(dist<110&&Math.abs(a.y-b.y)<70){b.hit=18;b.h-=type==='kick'?11:type==='grapple'?17:7;b.vx=(b.x>a.x?1:-1)*(type==='grapple'?12:7);toast(type==='grapple'?'SLAM!':type==='kick'?'HEAVY KICK':'HIT!')}}
$('start').onclick=()=>{if(ended){p.h=e.h=100;p.x=260;e.x=690;time=90;ended=false}active=true;$('overlay').classList.add('hidden');toast('FIGHT!')};

function update(dt){if(!active)return;time-=dt;if(time<=0){time=0;end(p.h>=e.h?'KNOCKOUT • YOU WIN':'THE VIPER WINS')}
p.s=Math.min(100,p.s+7*dt);e.s=Math.min(100,e.s+6*dt);
const dir=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0);p.vx=dir*210;if(dir)p.facing=dir;if(keys.w||keys.arrowup||keys[' ']){if(p.y>=408)p.vy=-520}if(keys.j)attack(p,e,'punch');if(keys.k)attack(p,e,'kick');if(keys.l)attack(p,e,'grapple');
aiTimer-=dt;if(aiTimer<=0){aiTimer=.55+Math.random()*1.1;const d=e.x-p.x;if(Math.abs(d)>95)e.vx=d>0?-145:145;else attack(e,p,['punch','kick','grapple'][Math.floor(Math.random()*3)])}else if(Math.abs(e.x-p.x)>100)e.vx=e.x>p.x?-145:145;
[p,e].forEach(a=>{a.vy+=1100*dt;a.x+=a.vx*dt;a.y+=a.vy*dt;if(a.y>410){a.y=410;a.vy=0}a.x=Math.max(95,Math.min(865,a.x));if(a.attack)a.attack--;if(a.hit)a.hit--;a.vx*=.82});
if(p.h<=0||e.h<=0)end(p.h>e.h?'YOU WIN':'THE VIPER WINS');
$('pHealth').style.width=p.h+'%';$('eHealth').style.width=e.h+'%';$('pStamina').style.width=p.s+'%';$('eStamina').style.width=e.s+'%';$('pState').textContent=p.hit?'HIT!':'READY';$('eState').textContent=e.hit?'HIT!':'READY';$('timer').textContent='00:'+String(Math.ceil(time)).padStart(2,'0')}
function end(text){ended=true;active=false;$('overlaySub').textContent=text;$('overlay').querySelector('h1').innerHTML=text.includes('WIN')?'VICTORY<br><span>LEGEND</span>':'MATCH<br><span>OVER</span>';$('start').innerHTML='BACK IN THE RING <b>→</b>';$('overlay').classList.remove('hidden')}

function drawFighter(a,main){ctx.save();ctx.translate(a.x,a.y);ctx.scale(a.facing,1);if(a.hit)ctx.rotate(.12);ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(0,13,58,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=main?'#d3a62d':'#98a0a9';ctx.beginPath();ctx.moveTo(-30,0);ctx.quadraticCurveTo(-38,-56,-20,-75);ctx.quadraticCurveTo(0,-92,25,-72);ctx.quadraticCurveTo(38,-50,28,0);ctx.closePath();ctx.fill();ctx.fillStyle=main?'#171b22':'#30353c';ctx.fillRect(-29,-52,58,18);ctx.fillStyle=main?'#d8d0bd':'#8e969d';ctx.beginPath();ctx.arc(0,-92,22,0,Math.PI*2);ctx.fill();ctx.fillStyle=main?'#3a2418':'#25292d';ctx.beginPath();ctx.arc(-2,-95,23,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle=main?'#efc736':'#cbd0d4';ctx.fillRect(-5,-66,10,6);ctx.fillStyle=main?'#191c22':'#24282e';ctx.fillRect(-23,-40,46,55);ctx.fillStyle=main?'#e5b72e':'#9ba3aa';ctx.fillRect(-18,-30,36,11);ctx.strokeStyle='#20242a';ctx.lineCap='round';ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(-25,-25);ctx.lineTo(-48,-2);ctx.moveTo(25,-25);ctx.lineTo(48,-2);ctx.stroke();ctx.lineWidth=16;ctx.beginPath();ctx.moveTo(-18,10);ctx.lineTo(-28,60);ctx.moveTo(18,10);ctx.lineTo(28,60);ctx.stroke();ctx.fillStyle='#171a20';ctx.beginPath();ctx.ellipse(-29,63,16,8,0,0,Math.PI*2);ctx.ellipse(29,63,16,8,0,0,Math.PI*2);ctx.fill();if(a.attack){ctx.strokeStyle=main?'#ffc400':'#d8dde2';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(25,-35);ctx.lineTo(65,-45);ctx.stroke()}ctx.restore()}

function draw(){ctx.clearRect(0,0,960,540);ctx.fillStyle='#11141b';ctx.fillRect(0,410,960,130);ctx.strokeStyle='#5a606a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(70,420);ctx.lineTo(890,420);ctx.stroke();ctx.strokeStyle='#a6adb7';ctx.globalAlpha=.35;for(let y=450;y<530;y+=28){ctx.beginPath();ctx.moveTo(70,y);ctx.lineTo(890,y);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#272c36';ctx.fillRect(70,410,820,12);ctx.fillStyle='#d0b675';ctx.fillRect(70,422,820,6);ctx.fillStyle='#5b2027';ctx.fillRect(70,428,820,112);ctx.strokeStyle='#15181f';ctx.lineWidth=12;ctx.beginPath();ctx.moveTo(72,410);ctx.lineTo(72,540);ctx.moveTo(888,410);ctx.lineTo(888,540);ctx.stroke();ctx.fillStyle='#15181f';ctx.fillRect(55,400,35,140);ctx.fillRect(870,400,35,140);drawFighter(p,true);drawFighter(e,false)}
function loop(now){let dt=Math.min(.033,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
